```dart
class Node {
  final int value;
  Node? next;
  Node(this.value);
}

void main() {
  final a = Node(1);
  a.next = Node(2);
  a.next!.next = Node(3);
  Node? n = a;
  var sum = 0;
  while (n != null) {
    sum += n.value;
    n = n.next;
  }
  print(sum);
}
```

